begin;
create table crm_private.meta_connections(organization_id uuid primary key references public.organizations(id)on delete cascade,generation uuid not null default gen_random_uuid(),state text not null default 'disconnected'check(state in('verified','reconnect','disconnected')),ciphertext text,expires_at timestamptz,connected_by uuid references auth.users(id),updated_at timestamptz not null default now());
create table crm_private.meta_oauth_states(hash text primary key,organization_id uuid not null references public.organizations(id)on delete cascade,actor_id uuid not null,session_hash text not null,generation uuid not null,expires_at timestamptz not null default now()+interval '10 minutes',used_at timestamptz);
create table crm_private.meta_accounts(organization_id uuid not null references public.organizations(id)on delete cascade,id text not null check(id~'^act_[0-9]+$'),name text not null,currency text not null check(currency~'^[A-Z]{3}$'),timezone text not null,generation uuid not null,selected boolean not null default false,interval_minutes integer not null default 60 check(interval_minutes between 15 and 1440),overlap_days integer not null default 30 check(overlap_days between 1 and 90),next_due_at timestamptz,current_snapshot uuid,last_success_at timestamptz,primary key(organization_id,id));
create table crm_private.meta_jobs(id uuid primary key default gen_random_uuid(),organization_id uuid not null,account_id text not null,generation uuid not null,state text not null default 'queued'check(state in('queued','running','retry','completed','failed','cancelled')),stage integer not null default 0 check(stage between 0 and 5),cursor text,lease uuid,lease_until timestamptz,next_attempt_at timestamptz not null default now(),retries integer not null default 0,since date not null,until date not null,currency text not null,timezone text not null,rows_processed integer not null default 0,error_code text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),published_at timestamptz,foreign key(organization_id,account_id)references crm_private.meta_accounts(organization_id,id)on delete cascade);
create unique index meta_one_active on crm_private.meta_jobs(organization_id,account_id)where state in('queued','running','retry');
create index meta_jobs_claim on crm_private.meta_jobs(state,next_attempt_at,lease_until);
alter table crm_private.meta_accounts add foreign key(current_snapshot)references crm_private.meta_jobs(id);
create table crm_private.meta_entities(job_id uuid not null references crm_private.meta_jobs(id)on delete cascade,kind text not null check(kind in('campaign','adset','creative','ad')),external_id text not null check(external_id~'^[0-9]+$'),data jsonb not null,primary key(job_id,kind,external_id));
create table crm_private.meta_daily(job_id uuid not null references crm_private.meta_jobs(id)on delete cascade,ad_id text not null,day date not null,campaign_id text,adset_id text,spend numeric(20,6)not null check(spend>=0),lead_actions numeric(20,6),actions jsonb not null,primary key(job_id,ad_id,day));
create table crm_private.meta_reviewed_links(organization_id uuid not null references public.organizations(id)on delete cascade,manual_ref uuid not null references public.ad_references(id)on delete cascade,meta_ref uuid not null references public.ad_references(id)on delete cascade,revision integer not null default 1,reviewed_by uuid not null references auth.users(id),reviewed_at timestamptz not null default now(),primary key(organization_id,manual_ref));
create table crm_private.meta_link_audit(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,actor_id uuid not null,occurred_at timestamptz not null default now(),before_data jsonb,after_data jsonb not null);
create table crm_private.meta_lead_eligibility(lead_id uuid primary key,organization_id uuid not null,eligibility jsonb not null,captured_at timestamptz not null default now(),foreign key(organization_id,lead_id)references public.leads(organization_id,id)on delete cascade);
alter table public.ad_references add column provider text not null default 'manual'check(provider in('manual','meta')),add column provider_account text,add column provider_external text,add column provider_status text,add column provider_synced_at timestamptz;
create unique index meta_reference_identity on public.ad_references(organization_id,provider,provider_account,kind,provider_external)where provider='meta';
create function crm_private.meta_protect_reference()returns trigger language plpgsql security definer set search_path=''as $$begin if OLD.provider='meta'and auth.uid()is not null then raise exception 'Meta references are provider-owned; use explicit reviewed links, not manual edits'using errcode='22023';end if;return NEW;end$$;
create trigger meta_reference_owner before update on public.ad_references for each row execute function crm_private.meta_protect_reference();
do $$declare t text;begin foreach t in array array['meta_connections','meta_oauth_states','meta_accounts','meta_jobs','meta_entities','meta_daily','meta_reviewed_links','meta_link_audit','meta_lead_eligibility']loop execute format('alter table crm_private.%I enable row level security',t);execute format('revoke all on crm_private.%I from public,anon,authenticated,service_role',t);end loop;end$$;
create function crm_private.meta_enqueue(org uuid,account text)returns uuid language plpgsql security definer set search_path=''as $$declare a crm_private.meta_accounts;c crm_private.meta_connections;job uuid;today date;begin
 perform pg_advisory_xact_lock(hashtextextended('meta:'||org::text||account,0));select * into a from crm_private.meta_accounts where organization_id=org and id=account;select * into c from crm_private.meta_connections where organization_id=org;
 if not a.selected or c.state<>'verified'or c.generation<>a.generation or c.expires_at<=now()or not exists(select 1 from public.organization_memberships where user_id=c.connected_by and organization_id=org and active and role='admin')then raise exception 'Verified selected account and active connector required'using errcode='42501';end if;
 today=(now()at time zone a.timezone)::date;insert into crm_private.meta_jobs(organization_id,account_id,generation,since,until,currency,timezone)values(org,account,c.generation,today-(a.overlap_days-1),today,a.currency,a.timezone)on conflict(organization_id,account_id)where state in('queued','running','retry')do update set updated_at=meta_jobs.updated_at returning id into job;return job;
end$$;
create function public.crm_meta_admin(p_op text,p_input jsonb default '{}')returns jsonb language plpgsql security definer set search_path=''as $$declare org uuid:=crm_private.import_admin();g uuid;s crm_private.meta_oauth_states;job uuid;begin
 if p_op='oauth_begin'then if coalesce(p_input->>'hash','')!~'^[a-f0-9]{64}$'or coalesce(p_input->>'session_hash','')!~'^[a-f0-9]{64}$'then raise exception 'Invalid state'using errcode='22023';end if;insert into crm_private.meta_connections(organization_id)values(org)on conflict do nothing;select generation into g from crm_private.meta_connections where organization_id=org;insert into crm_private.meta_oauth_states(hash,organization_id,actor_id,session_hash,generation)values(p_input->>'hash',org,auth.uid(),p_input->>'session_hash',g);return jsonb_build_object('generation',g);
 elsif p_op='oauth_consume'then select * into s from crm_private.meta_oauth_states where hash=p_input->>'hash'and organization_id=org and actor_id=auth.uid()for update;if not found or s.session_hash is distinct from p_input->>'session_hash'or s.used_at is not null or s.expires_at<=now()or s.generation<>(select generation from crm_private.meta_connections where organization_id=org)then raise exception 'OAuth state expired, replayed or from another session'using errcode='42501';end if;update crm_private.meta_oauth_states set used_at=now()where hash=s.hash;return jsonb_build_object('generation',s.generation);
 elsif p_op='queue'then job=crm_private.meta_enqueue(org,p_input->>'account');return jsonb_build_object('job_id',job);
 elsif p_op='disconnect'then update crm_private.meta_connections set state='disconnected',ciphertext=null,generation=gen_random_uuid(),updated_at=now()where organization_id=org;update crm_private.meta_accounts set selected=false,next_due_at=null where organization_id=org;update crm_private.meta_jobs set state='cancelled',error_code='disconnected',lease=null where organization_id=org and state in('queued','running','retry');return '{"disconnected":true}';
 else raise exception 'Unsupported Meta operation'using errcode='22023';end if;
end$$;
create function public.crm_meta_service(p_org uuid,p_actor uuid,p_op text,p_input jsonb default '{}')returns jsonb language plpgsql security definer set search_path=''as $$declare c crm_private.meta_connections;s crm_private.meta_oauth_states;a jsonb;g uuid;job uuid;begin
 if not exists(select 1 from public.organization_memberships where user_id=p_actor and organization_id=p_org and active and role='admin')then raise exception 'Active Admin required'using errcode='42501';end if;
 select * into c from crm_private.meta_connections where organization_id=p_org for update;
 if p_op='read'then return jsonb_build_object('generation',c.generation,'ciphertext',c.ciphertext,'state',c.state,'expires_at',c.expires_at);
 elsif p_op='store'then select * into s from crm_private.meta_oauth_states where hash=p_input->>'state_hash'and actor_id=p_actor and organization_id=p_org;if s.used_at is null or s.used_at<now()-interval '5 minutes'or s.generation is distinct from c.generation or coalesce(p_input->>'ciphertext','')not like 'v1.%'or length(p_input->>'ciphertext')>16000 or p_input->>'expires_at'is null or(p_input->>'expires_at')::timestamptz<=now()or jsonb_typeof(p_input->'accounts')is distinct from 'array'or jsonb_array_length(p_input->'accounts')>500 then raise exception 'Stale or invalid verified connection'using errcode='42501';end if;
 g=gen_random_uuid();update crm_private.meta_connections set generation=g,state='verified',ciphertext=p_input->>'ciphertext',expires_at=(p_input->>'expires_at')::timestamptz,connected_by=p_actor,updated_at=now()where organization_id=p_org;update crm_private.meta_jobs set state='cancelled',error_code='reconnected',lease=null where organization_id=p_org and state in('queued','running','retry');
 for a in select * from jsonb_array_elements(p_input->'accounts')loop if a->>'id'!~'^act_[0-9]+$'or a->>'currency'!~'^[A-Z]{3}$'then raise exception 'Invalid verified account'using errcode='22023';end if;perform now()at time zone(a->>'timezone');insert into crm_private.meta_accounts(organization_id,id,name,currency,timezone,generation)values(p_org,a->>'id',left(a->>'name',200),a->>'currency',a->>'timezone',g)on conflict(organization_id,id)do update set name=excluded.name,currency=excluded.currency,timezone=excluded.timezone,generation=g,next_due_at=case when meta_accounts.selected then now()else null end;end loop;return '{"verified":true}';
 elsif p_op='select'then if c.state<>'verified'or c.generation is distinct from(p_input->>'generation')::uuid or not exists(select 1 from crm_private.meta_accounts where organization_id=p_org and id=p_input->'account'->>'id'and generation=c.generation)then raise exception 'Account not discovered for this connection'using errcode='42501';end if;a=p_input->'account';update crm_private.meta_accounts set name=left(a->>'name',200),currency=a->>'currency',timezone=a->>'timezone',selected=true,interval_minutes=coalesce((p_input->>'interval')::integer,60),overlap_days=coalesce((p_input->>'days')::integer,30),next_due_at=now()where organization_id=p_org and id=a->>'id';job=crm_private.meta_enqueue(p_org,a->>'id');return jsonb_build_object('job_id',job);
 elsif p_op='reconnect'then update crm_private.meta_connections set state='reconnect',updated_at=now()where organization_id=p_org;update crm_private.meta_jobs set state='cancelled',error_code='reconnect',lease=null where organization_id=p_org and state in('queued','running','retry');return '{"reconnect":true}';
 else raise exception 'Unsupported service operation'using errcode='22023';end if;
end$$;
create function public.crm_meta_status()returns jsonb language plpgsql stable security definer set search_path=''as $$declare org uuid;begin select organization_id into org from public.organization_memberships where user_id=auth.uid()and active and role='admin';if org is null then raise exception 'Active Admin required'using errcode='42501';end if;return jsonb_build_object('connection',(select jsonb_build_object('state',case when state='verified'and expires_at<=now()then 'reconnect'else state end,'expires_at',expires_at,'updated_at',updated_at)from crm_private.meta_connections where organization_id=org),'accounts',coalesce((select jsonb_agg(x)from(select a.id,a.name,a.currency,a.timezone,a.selected,a.interval_minutes,a.overlap_days,a.last_success_at,a.next_due_at,coalesce((select jsonb_agg(j)from(select id,state,stage,retries,rows_processed,since,until,error_code,updated_at from crm_private.meta_jobs where organization_id=org and account_id=a.id order by created_at desc limit 3)j),'[]'::jsonb)jobs from crm_private.meta_accounts a join crm_private.meta_connections c using(organization_id)where a.organization_id=org and a.generation=c.generation order by a.name limit 100)x),'[]'::jsonb));end$$;
create function public.crm_meta_link(p_meta uuid,p_manual uuid,p_revision integer)returns jsonb language plpgsql security definer set search_path=''as $$declare org uuid:=crm_private.import_admin();a public.ad_references;b public.ad_references;old crm_private.meta_reviewed_links;saved crm_private.meta_reviewed_links;begin
 perform pg_advisory_xact_lock(hashtextextended('meta-link:'||org::text||p_manual::text,0));select * into a from public.ad_references where id=p_meta and organization_id=org and provider='meta';select * into b from public.ad_references where id=p_manual and organization_id=org and provider='manual';if a.id is null or b.id is null or a.kind<>b.kind or a.archived or b.archived then raise exception 'Choose same-organization Meta and manual references of the same kind'using errcode='42501';end if;select * into old from crm_private.meta_reviewed_links where organization_id=org and manual_ref=p_manual for update;if coalesce(old.revision,0)<>p_revision then raise exception 'Link changed; reload'using errcode='PT409';end if;insert into crm_private.meta_reviewed_links(organization_id,manual_ref,meta_ref,reviewed_by)values(org,p_manual,p_meta,auth.uid())on conflict(organization_id,manual_ref)do update set meta_ref=excluded.meta_ref,revision=meta_reviewed_links.revision+1,reviewed_by=auth.uid(),reviewed_at=now()returning * into saved;insert into crm_private.meta_link_audit(organization_id,actor_id,before_data,after_data)values(org,auth.uid(),case when old.manual_ref is null then null else to_jsonb(old)end,to_jsonb(saved));return jsonb_build_object('revision',saved.revision,'prospective',true);end$$;
create function public.crm_meta_links(p_page integer default 1)returns jsonb language plpgsql stable security definer set search_path=''as $$declare org uuid;begin select organization_id into org from public.organization_memberships where user_id=auth.uid()and active and role='admin';if org is null then raise exception 'Active Admin required'using errcode='42501';end if;if p_page is null or p_page<1 or p_page>100000 then raise exception 'Invalid page'using errcode='22023';end if;return jsonb_build_object('references',coalesce((select jsonb_agg(x)from(select id,kind,name,provider,provider_account,provider_external,provider_status,archived from public.ad_references where organization_id=org order by provider,name,id limit 20 offset(p_page-1)*20)x),'[]'::jsonb),'total',(select count(*)from public.ad_references where organization_id=org),'links',coalesce((select jsonb_agg(x)from(select manual_ref,meta_ref,revision,reviewed_at from crm_private.meta_reviewed_links where organization_id=org order by reviewed_at desc limit 20 offset(p_page-1)*20)x),'[]'::jsonb));end$$;
create function crm_private.meta_capture_eligibility()returns trigger language plpgsql security definer set search_path=''as $$declare k text;r public.ad_references;linked public.ad_references;e jsonb:='{}';accounts integer;begin
 foreach k in array array['campaign','ad','creative']loop
 select * into r from public.ad_references where id=nullif(NEW.snapshot->k->>'id','')::uuid and organization_id=NEW.organization_id;
 if r.provider='meta'then linked=r;else select m.* into linked from crm_private.meta_reviewed_links l join public.ad_references m on m.id=l.meta_ref and m.organization_id=NEW.organization_id and m.kind=k and m.provider='meta'where l.organization_id=NEW.organization_id and l.manual_ref=r.id;end if;
 if linked.id is not null then e=e||jsonb_build_object(k,jsonb_build_object('account',linked.provider_account,'id',linked.provider_external,'reference_id',linked.id));end if;
 end loop;select count(distinct value->>'account')into accounts from jsonb_each(e);if accounts>1 then e='{}';end if;insert into crm_private.meta_lead_eligibility(lead_id,organization_id,eligibility)values(NEW.lead_id,NEW.organization_id,e);return NEW;end$$;
create trigger meta_eligibility after insert on crm_private.ad_attribution_snapshots for each row execute function crm_private.meta_capture_eligibility();
revoke all on function crm_private.meta_capture_eligibility(),crm_private.meta_protect_reference(),crm_private.meta_enqueue(uuid,text)from public,anon,authenticated,service_role;
revoke all on function public.crm_meta_admin(text,jsonb),public.crm_meta_status(),public.crm_meta_link(uuid,uuid,integer),public.crm_meta_links(integer),public.crm_meta_service(uuid,uuid,text,jsonb)from public,anon,authenticated,service_role;
grant execute on function public.crm_meta_admin(text,jsonb),public.crm_meta_status(),public.crm_meta_link(uuid,uuid,integer),public.crm_meta_links(integer)to authenticated;
grant execute on function public.crm_meta_service(uuid,uuid,text,jsonb)to service_role;
create or replace function public.ad_attribution_admin(p_page integer default 1)returns jsonb language plpgsql stable security definer set search_path='' as $$
declare org uuid;begin
 select organization_id into org from public.organization_memberships where user_id=auth.uid()and active and role='admin';
 if org is null then raise exception 'Active Admin required' using errcode='42501';end if;
 if p_page is null or p_page<1 or p_page>100000 then raise exception 'Invalid page' using errcode='22023';end if;
 return jsonb_build_object('references',coalesce((select jsonb_agg(x)from(select id,kind,name,external_id,campaign_id,creative_id,campaign_ref,archived,revision,provider,provider_account,provider_external,provider_status from public.ad_references where organization_id=org order by created_at desc,id limit 20 offset(p_page-1)*20)x),'[]'::jsonb),
 'reference_total',(select count(*)from public.ad_references where organization_id=org),
 'mappings',coalesce((select jsonb_agg(x)from(select m.id,m.source_id,m.form_version,m.reported_kind,m.reported_value,m.reference_id,m.active,m.revision,m.reviewed_at,p.full_name reviewed_by from public.ad_mapping_rules m left join public.staff_profiles p on p.id=m.reviewed_by where m.organization_id=org order by m.reviewed_at desc,m.id limit 20 offset(p_page-1)*20)x),'[]'::jsonb),
 'mapping_total',(select count(*)from public.ad_mapping_rules where organization_id=org),
 'versions',coalesce((select jsonb_agg(x)from(select v.source_id,v.version_key,s.name source_name from public.source_form_versions v join public.ingestion_sources s on s.id=v.source_id and s.organization_id=org where v.organization_id=org order by s.name,v.version_key limit 500)x),'[]'::jsonb),
 'audit',coalesce((select jsonb_agg(x)from(select a.module,a.record_id,a.occurred_at,p.full_name actor,a.before_data,a.after_data from crm_private.ad_mapping_audit a left join public.staff_profiles p on p.id=a.actor_id where a.organization_id=org order by a.occurred_at desc,a.id limit 20 offset(p_page-1)*20)x),'[]'::jsonb),'audit_total',(select count(*)from crm_private.ad_mapping_audit where organization_id=org));
end$$;

commit;
